begin;
create extension if not exists pgtap with schema extensions;
select plan(25);
insert into public.invitations(code,expires_at) values('TEST-AAAA',now()+interval '1 day'),('TEST-BBBB',now()+interval '1 day');
insert into auth.users(id,raw_user_meta_data) values ('11111111-1111-4111-8111-111111111111','{"invite_code":"TEST-AAAA"}'), ('22222222-2222-4222-8222-222222222222','{"invite_code":"TEST-BBBB"}');
select is((select count(*) from public.memberships),2::bigint,'signup automatically joins TBellini');
select is((select count(*) from public.profiles),2::bigint,'registered profiles created separately');
insert into public.events(id,owner_id,title,starts_at) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','Community event',now());
insert into public.people(owner_id,display_name) values('11111111-1111-4111-8111-111111111111','Private person');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$insert into public.event_user_tags(event_id,user_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111')$$,'author tags registered member');
select throws_ok($$insert into public.event_user_tags(event_id,user_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111')$$,'23503',null,'unregistered user cannot be tagged');
select throws_ok($$update public.events set owner_id='22222222-2222-4222-8222-222222222222' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,'23514',null,'author identity immutable');
select throws_ok($$update public.events set community_id='99999999-9999-4999-8999-999999999999' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,'23514',null,'community identity immutable');
select lives_ok($$update public.events set title='Corrected event' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$,'author corrects event');
select lives_ok($$update public.profiles set display_name='Author' where id='11111111-1111-4111-8111-111111111111'$$,'own display name editable');
select throws_ok($$insert into public.memberships(community_id,user_id) values('00000000-0000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111')$$,'42501',null,'clients cannot manage membership');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.events),1::bigint,'other member can see event');
select is((select count(*) from public.people),0::bigint,'private archive people remain hidden');
select is((select count(*) from public.event_user_tags),1::bigint,'member can see registered tags');
select is((select count(*) from public.event_rsvps),0::bigint,'tagging does not create an RSVP');
with removed as(delete from public.event_user_tags returning user_id) select is((select count(*) from removed),0::bigint,'tagged member cannot delete author tag');
with changed as(update public.events set title='Hijack' returning id) select is((select count(*) from changed),0::bigint,'other member cannot edit');
with removed as(delete from public.events returning id) select is((select count(*) from removed),0::bigint,'other member cannot delete');
select throws_ok($$insert into public.event_user_tags(event_id,user_id,tagged_by) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222')$$,'42501',null,'non-author cannot tag');
select lives_ok($$insert into public.event_rsvps(event_id,user_id,status) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','going')$$,'member chooses own going RSVP');
select throws_ok($$update public.event_rsvps set user_id='11111111-1111-4111-8111-111111111111'$$,'23514',null,'RSVP identity cannot be transferred');
select lives_ok($$update public.event_rsvps set status='interested' where user_id='22222222-2222-4222-8222-222222222222'$$,'member changes own RSVP');
select throws_ok($$insert into public.event_rsvps(event_id,user_id,status) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','going')$$,'42501',null,'cannot RSVP as another user');
select throws_ok($$update public.event_rsvps set status='maybe' where user_id='22222222-2222-4222-8222-222222222222'$$,'23514',null,'RSVP status restricted');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
with removed as(delete from public.event_rsvps returning user_id) select is((select count(*) from removed),0::bigint,'event author cannot clear another RSVP');
select is((select count(*) from public.event_rsvps where status='interested'),1::bigint,'community can see RSVP status');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select lives_ok($$delete from public.event_rsvps where user_id='22222222-2222-4222-8222-222222222222'$$,'member clears own RSVP');
reset role;
select * from finish();
rollback;
